const fs = require('fs');
const p = 'src/ProfileSettings.tsx';
let s = fs.readFileSync(p, 'utf8');

function replaceOnce(from, to) {
  if (!s.includes(from)) { console.error('NOT FOUND:\n' + from); process.exit(1); }
  s = s.replace(from, to);
}

// 1. Baseline state: last saved values; dirty-check and cancel use it.
replaceOnce(
`  const [values, setValues] = React.useState<ProfileSettingsValues>(initial);
`,
`  // Последнее сохранённое состояние: с ним сравниваем изменения, к нему откатывает «Отмена».
  const [baseline, setBaseline] = React.useState<ProfileSettingsValues>(initial);
  const [values, setValues] = React.useState<ProfileSettingsValues>(initial);
`);

// 2. Object URL handling: never revoke the URL that is part of the saved baseline.
replaceOnce(
`  const fileInputRef = React.useRef<HTMLInputElement>(null);
  // Object URL для локально выбранного файла. Освобождаем при замене/размонтировании.
  const objectUrlRef = React.useRef<string | null>(null);

  const revokeObjectUrl = React.useCallback(() => {
    if (objectUrlRef.current) {
      URL.revokeObjectURL(objectUrlRef.current);
      objectUrlRef.current = null;
    }
  }, []);

  React.useEffect(() => revokeObjectUrl, [revokeObjectUrl]);
`,
`  const fileInputRef = React.useRef<HTMLInputElement>(null);
  // Object URL для ещё не сохранённого локально выбранного файла.
  // Освобождаем при замене, отмене и размонтировании; сохранённый URL не трогаем.
  const pendingObjectUrlRef = React.useRef<string | null>(null);

  const revokePendingObjectUrl = React.useCallback(() => {
    if (pendingObjectUrlRef.current) {
      URL.revokeObjectURL(pendingObjectUrlRef.current);
      pendingObjectUrlRef.current = null;
    }
  }, []);

  React.useEffect(() => revokePendingObjectUrl, [revokePendingObjectUrl]);
`);

replaceOnce(
`    revokeObjectUrl();
    const url = URL.createObjectURL(file);
    objectUrlRef.current = url;
    setAvatarError(null);
    update("avatarUrl", url);
  };

  const handleAvatarRemove = () => {
    revokeObjectUrl();
    setAvatarError(null);
    update("avatarUrl", null);
  };
`,
`    revokePendingObjectUrl();
    const url = URL.createObjectURL(file);
    pendingObjectUrlRef.current = url;
    setAvatarError(null);
    update("avatarUrl", url);
  };

  const handleAvatarRemove = () => {
    revokePendingObjectUrl();
    setAvatarError(null);
    update("avatarUrl", null);
  };
`);

// 3. Dirty-check against baseline.
replaceOnce(
`  const isDirty = React.useMemo(
    () => JSON.stringify(values) !== JSON.stringify(initial),
    [values, initial],
  );
`,
`  const isDirty = React.useMemo(
    () => JSON.stringify(values) !== JSON.stringify(baseline),
    [values, baseline],
  );
`);

// 4. Save: commit values to baseline; pending object URL becomes the saved one.
replaceOnce(
`    onSave?.(result);
    setSaved(true);
  };

  const handleCancel = () => {
    revokeObjectUrl();
    setValues(initial);
    setTouched({});
    setSubmitted(false);
    setAvatarError(null);
    setSaved(false);
    onCancel?.();
  };
`,
`    onSave?.(result);
    // Загруженный аватар теперь часть сохранённого состояния — его URL больше не «ожидающий».
    pendingObjectUrlRef.current = null;
    setBaseline(result);
    setValues(result);
    setTouched({});
    setSubmitted(false);
    setSaved(true);
  };

  const handleCancel = () => {
    revokePendingObjectUrl();
    setValues(baseline);
    setTouched({});
    setSubmitted(false);
    setAvatarError(null);
    setSaved(false);
    onCancel?.();
  };
`);

// 5. Buttons: Save enabled only when there is something to save.
replaceOnce(`            disabled={!isDirty && !submitted}`, `            disabled={!isDirty}`);

fs.writeFileSync(p, s);
console.log('ok');
